// @FIGURE_CODE_BEGIN
var ACCENT = '#d43d1a';
var NAVY = '#123a6b';

setPlotFrame({ xDomain: [-8.2, 8.2], yDomain: [-8.2, 8.2], margin: 12 });
var g = _plotFrame.draw;
var svgNode = g.node.ownerSVGElement;
svgNode.setAttribute('viewBox', '0 0 ' + _plotFrame.width + ' ' + _plotFrame.height);
var gStatic = g.group(), gDyn = g.group(), gTop = g.group();

function redrawStatic() {
  gStatic.clear();
  // concentric circles
  for (var r = 1; r <= 7; r++) {
    gStatic.circle().radius((plotX(r) - plotX(0))).center(plotX(0), plotY(0))
      .fill('none').stroke({ color: '#c8c8c8', width: 1 });
  }
  // spokes every 22.5°
  for (var k = 0; k < 16; k++) {
    var a = k * Math.PI / 8;
    gStatic.line(plotX(0), plotY(0), plotX(7 * Math.cos(a)), plotY(7 * Math.sin(a)))
      .stroke({ color: '#d4d4d4', width: 1 });
  }
  // axes with arrowheads
  function arrow(x1, y1, x2, y2) {
    gStatic.line(x1, y1, x2, y2).stroke({ color: '#333', width: 1.5 });
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var s = 7;
    gStatic.polygon([
      [x2, y2],
      [x2 - s * Math.cos(ang - 0.4), y2 - s * Math.sin(ang - 0.4)],
      [x2 - s * Math.cos(ang + 0.4), y2 - s * Math.sin(ang + 0.4)]
    ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill('#333');
  }
  arrow(plotX(-7.7), plotY(0), plotX(7.7), plotY(0));
  arrow(plotX(0), plotY(-7.7), plotX(0), plotY(7.7));
  // tick labels
  for (var i = -7; i <= 7; i++) {
    if (i === 0) continue;
    gStatic.plain(String(i)).font({ size: 11, family: 'sans-serif' }).fill('#333')
      .center(plotX(i), plotY(0) + 12);
    gStatic.plain(String(i)).font({ size: 11, family: 'sans-serif' }).fill('#333')
      .center(plotX(0) + 10, plotY(i));
  }
  // spiral r = θ, 0..2π
  var pts = [];
  for (var t = 0; t <= 600; t++) {
    var th = t / 600 * 2 * Math.PI;
    pts.push([plotX(th * Math.cos(th)), plotY(th * Math.sin(th))]);
  }
  gStatic.polyline(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill('none').stroke({ color: NAVY, width: 3, linecap: 'round' });
}

var SAMPLES = [
  { t: Math.PI / 4, label: '(π/4, π/4)' },
  { t: Math.PI / 2, label: '(π/2, π/2)' },
  { t: Math.PI, label: '(π, π)' },
  { t: 5 * Math.PI / 4, label: '(5π/4, 5π/4)' },
  { t: 7 * Math.PI / 4, label: '(7π/4, 7π/4)' },
  { t: 2 * Math.PI, label: '(2π, 2π)' }
];
// label offsets in world units [dx, dy] to keep text off the curve
var LBL_OFF = [[0.8, 0.7], [-0.2, 0.9], [0, 0.75], [-0.3, -0.7], [0.6, -0.7], [0, 0.75]];

var dotEls = [];
function drawSamples() {
  SAMPLES.forEach(function (s, idx) {
    var x = plotX(s.t * Math.cos(s.t)), y = plotY(s.t * Math.sin(s.t));
    var d = gTop.circle().radius(4.5).center(x, y).fill('#000')
      .css('cursor', 'pointer');
    d.on('mousemove', function (e) { showTooltip(s.label + ' — click to see its ray & circle', e); });
    d.on('mouseleave', hideTooltip);
    d.on('click', function () { probePoint(idx); });
    dotEls.push(d);
    var off = LBL_OFF[idx];
    var lx = plotX(s.t * Math.cos(s.t) + off[0]), ly = plotY(s.t * Math.sin(s.t) + off[1]);
    var txt = gTop.plain(s.label).font({ size: 12, family: 'serif' }).fill('#000')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
      .center(lx, ly);
    txt.on('click', function () { probePoint(idx); }).css('cursor', 'pointer');
  });
}

var probeGroup = gDyn.group();
function probePoint(idx) {
  var s = SAMPLES[idx];
  probeGroup.clear();
  var x = plotX(s.t * Math.cos(s.t)), y = plotY(s.t * Math.sin(s.t));
  // angle ray
  probeGroup.line(plotX(0), plotY(0), x, y).stroke({ color: ACCENT, width: 2 });
  // radius circle
  probeGroup.circle().radius(plotX(s.t) - plotX(0)).center(plotX(0), plotY(0))
    .fill('none').stroke({ color: ACCENT, width: 2, dasharray: '6,4' });
  showPopup('Point ' + s.label,
    'Both entries are the same number: θ = ' + s.t.toFixed(3) +
    ' radians sets the ray direction, and r = θ = ' + s.t.toFixed(3) +
    ' sets the radius of the circle the point sits on. In r = θ the angle swept so far IS the distance from the origin.');
}

var markerGroup = gDyn.group();
var readout = null;
function update_thetaSweep(v) {
  markerGroup.clear();
  var x = plotX(v * Math.cos(v)), y = plotY(v * Math.sin(v));
  markerGroup.line(plotX(0), plotY(0), x, y).stroke({ color: '#2a7f3e', width: 1.5 });
  markerGroup.circle().radius(5).center(x, y).fill('#2a7f3e').stroke({ color: '#fff', width: 1 });
  readout = markerGroup.plain('(θ, r) = (' + v.toFixed(2) + ', ' + v.toFixed(2) + ')')
    .font({ size: 12, family: 'sans-serif' }).fill('#2a7f3e')
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  var lx = Math.min(Math.max(x + 10, 10), _plotFrame.width - 150);
  var ly = Math.max(y - 18, 12);
  readout.move(lx, ly);
}

// trace animation
var tracing = false;
function trigger_traceSpiral() {
  if (tracing) return;
  tracing = true;
  var start = null, DUR = 4000;
  function frame(ts) {
    if (!start) start = ts;
    var p = Math.min((ts - start) / DUR, 1);
    var th = p * 2 * Math.PI;
    document.getElementById('thetaSweepInput').value = th;
    document.getElementById('thetaSweepVal').value = th.toFixed(2);
    update_thetaSweep(th);
    if (p < 1) requestAnimationFrame(frame); else tracing = false;
  }
  requestAnimationFrame(frame);
}

// demo steps
var STEPS = [
  { title: 'A point on the spiral', theta: 1.571,
    narration: 'Drag θ to π/2: the marker sits directly above the origin at distance ≈ 1.57 — the readout shows r equals θ.' },
  { title: 'Half a turn', theta: 3.142,
    narration: 'At θ = π the marker crosses the negative axis at distance ≈ 3.14 — matching the dot (π, π).' },
  { title: 'One full turn', theta: 6.283,
    narration: 'At θ = 2π the curve ends at ≈ 6.28 on the positive axis, the dot (2π, 2π). Each turn adds exactly 2π to the radius.' }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = i;
  var s = STEPS[i];
  document.getElementById('thetaSweepInput').value = s.theta;
  document.getElementById('thetaSweepVal').value = s.theta.toFixed(2);
  update_thetaSweep(s.theta);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / 3';
}
function prevStep() { applyStep(Math.max(0, stepIdx - 1)); }
function nextStep() { applyStep(Math.min(2, stepIdx + 1)); }

function renderAll() {
  g.viewbox(0, 0, _plotFrame.width, _plotFrame.height);
  redrawStatic();
  gTop.clear(); dotEls = [];
  drawSamples();
  update_thetaSweep(+document.getElementById('thetaSweepInput').value);
}
renderAll();
applyStep(0);
document.addEventListener('fig-resize', function () {
  // grid/dots/labels are drawn in pixel coords; rebuild at the new size
  probeGroup.clear();
  renderAll();
});
window.__markRendered();
// @FIGURE_CODE_END

