    gStatic.polygon([[x2, y2],
      [x2 - s * Math.cos(ang - 0.42), y2 - s * Math.sin(ang - 0.42)],
      [x2 - s * Math.cos(ang + 0.42), y2 - s * Math.sin(ang + 0.42)]]
      .map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill('#222');
  }
  arrow(plotX(-7.75), plotY(0), plotX(7.75), plotY(0));
  arrow(plotX(0), plotY(-7.75), plotX(0), plotY(7.75));
  for (var i = -7; i <= 7; i++) {
    if (i === 0) continue;
    var px = plotX(i), py0 = plotY(0), ox = plotX(0), pyi = plotY(i);
    gStatic.line(px, py0 - SZ.tick, px, py0 + SZ.tick).stroke({ color: '#222', width: SZ.axisW * 0.7 });
    gStatic.line(ox - SZ.tick, pyi, ox + SZ.tick, pyi).stroke({ color: '#222', width: SZ.axisW * 0.7 });
  }
  for (var j = -7; j <= 7; j++) {
    if (j === 0) continue;
    gStatic.plain(String(j)).font({ size: SZ.font, family: 'sans-serif' }).fill('#333')
      .center(plotX(j), plotY(0) + SZ.font * 1.15);
    gStatic.plain(String(j)).font({ size: SZ.font, family: 'sans-serif' }).fill('#333')
      .center(plotX(0) - SZ.font * 0.9, plotY(j));
  }
  // spiral r = θ, 0..2π
  var pts = [];
  for (var t = 0; t <= 700; t++) {
    var th = t / 700 * 2 * Math.PI;
    pts.push([plotX(th * Math.cos(th)), plotY(th * Math.sin(th))]);
  }
  gStatic.polyline(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill('none').stroke({ color: NAVY, width: SZ.spiralW, linecap: 'round' });
}

var SAMPLES = [
  { t: Math.PI / 4, label: '(π/4, π/4)' },
  { t: Math.PI / 2, label: '(π/2, π/2)' },
  { t: Math.PI, label: '(π, π)' },
  { t: 5 * Math.PI / 4, label: '(5π/4, 5π/4)' },
  { t: 7 * Math.PI / 4, label: '(7π/4, 7π/4)' },
  { t: 2 * Math.PI, label: '(2π, 2π)' }
];
// world-space label offsets chosen to match the source placement (open whitespace, off the curve)
var LBL_OFF = [
  [0.95, 0.85],   // π/4: upper-right of dot
  [0.15, 1.00],   // π/2: directly above
  [-1.30, 0.65],  // π:   left of dot, just above axis
  [-0.75, -0.60], // 5π/4: lower-left
  [0.55, -0.85],  // 7π/4: just below
  [-0.95, 0.85]   // 2π:  above-left of endpoint
];

function drawSamples() {
  gTop.clear();
  SAMPLES.forEach(function (s, idx) {
    var x = plotX(s.t * Math.cos(s.t)), y = plotY(s.t * Math.sin(s.t));
    var d = gTop.circle().radius(SZ.dotR).center(x, y).fill('#000').css('cursor', 'pointer');
    d.on('mousemove', function (e) { showTooltip(s.label + ' — θ and r are the same number. Click to light its ray & circle.', e); });
    d.on('mouseleave', hideTooltip);
    d.on('click', function () { probePoint(idx); });
    var off = LBL_OFF[idx];
    var lx = plotX(s.t * Math.cos(s.t) + off[0]);
    var ly = plotY(s.t * Math.sin(s.t) + off[1]);
    var txt = halo(gTop.plain(s.label).font({ size: SZ.sampleFont, family: 'serif' }).fill('#000'))
      .center(lx, ly).css('cursor', 'pointer');
    txt.on('mousemove', function (e) { showTooltip(s.label + ' — click to highlight', e); });
    txt.on('mouseleave', hideTooltip);
    txt.on('click', function () { probePoint(idx); });
  });
}

function probePoint(idx) {
  var s = SAMPLES[idx];
  probeGroup.clear();
  var x = plotX(s.t * Math.cos(s.t)), y = plotY(s.t * Math.sin(s.t));
  probeGroup.circle().radius(s.t * _plotFrame.sx).center(plotX(0), plotY(0))
    .fill('none').stroke({ color: ACCENT, width: SZ.spiralW * 0.7, dasharray: '6,4' });
  probeGroup.line(plotX(0), plotY(0), x, y).stroke({ color: ACCENT, width: SZ.spiralW * 0.7 });
  // tie the slider to the clicked point so r = θ stays visible at the marker too
  document.getElementById('thetaSweepInput').value = s.t;
  document.getElementById('thetaSweepVal').value = s.t.toFixed(2);
  update_thetaSweep(s.t);
  showPopup('Point ' + s.label,
    'Both entries are the same number: θ = ' + s.t.toFixed(3) +
    ' rad sets the ray direction, and r = θ = ' + s.t.toFixed(3) +
    ' is the radius of the dashed circle the point lies on. In r = θ the angle swept so far IS the distance from the origin.');
}

function update_thetaSweep(v) {
  markerGroup.clear();
  var x = plotX(v * Math.cos(v)), y = plotY(v * Math.sin(v));
  markerGroup.line(plotX(0), plotY(0), x, y).stroke({ color: '#2a7f3e', width: SZ.spiralW * 0.55 });
  markerGroup.circle().radius(SZ.dotR * 1.1).center(x, y).fill('#2a7f3e').stroke({ color: '#fff', width: 1 });
  var W = _plotFrame.width;
  var readout = halo(markerGroup.plain('(θ, r) = (' + v.toFixed(2) + ', ' + v.toFixed(2) + ')')
    .font({ size: SZ.sampleFont * 0.92, family: 'sans-serif' }).fill('#1d5c2c'));
  var lx = Math.min(Math.max(x + SZ.dotR + 4, 6), W - 8);
  var ly = Math.max(y - SZ.dotR - 6, SZ.sampleFont);
  // use right-anchored text when near the right edge
  if (x > W - 150) { readout.attr('text-anchor', 'end').move(Math.max(x - SZ.dotR - 4, 6), ly); }
  else { readout.move(lx, ly); }
}

var tracing = false;
function trigger_traceSpiral() {
  if (tracing) return;
  tracing = true;
  probeGroup.clear();
  var btn = document.getElementById('traceBtn');
  if (btn) btn.disabled = true;
  var start = null, DUR = 4500;
  function frame(ts) {
    if (!start) start = ts;
    var p = Math.min((ts - start) / DUR, 1);
    var th = p * 2 * Math.PI;
    document.getElementById('thetaSweepInput').value = th;
    document.getElementById('thetaSweepVal').value = th.toFixed(2);
    update_thetaSweep(th);
    if (p < 1) requestAnimationFrame(frame);
    else { tracing = false; if (btn) btn.disabled = false; }
  }
  requestAnimationFrame(frame);
}

var STEPS = [
  { theta: 1.571,
    narration: 'Drag θ to π/2: the marker sits directly above the origin at distance ≈ 1.57 — the readout shows r equals θ. The spiral\'s distance from the center tracks the angle swept.' },
  { theta: 3.142,
    narration: 'At θ = π the marker crosses the negative axis at distance ≈ 3.14 — one half-turn out, matching the labeled dot (π, π). Click that dot to see its ray and circle.' },
  { theta: 6.283,
    narration: 'At θ = 2π the curve ends on the positive axis at ≈ 6.28, the dot (2π, 2π). The gap between successive crossings of the same direction is a constant 2π: the radius grew by exactly 2π per revolution.' }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  document.getElementById('thetaSweepInput').value = s.theta;
  document.getElementById('thetaSweepVal').value = s.theta.toFixed(2);
  update_thetaSweep(s.theta);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
}
function prevStep() { applyStep(stepIdx - 1); }
function nextStep() { applyStep(stepIdx + 1); }

function renderAll() {
  fitIsotropic();
  g.viewbox(0, 0, _plotFrame.width, _plotFrame.height);
  sizes();
  redrawStatic();
  drawSamples();
  update_thetaSweep(+document.getElementById('thetaSweepInput').value || 1.571);
}

renderAll();
applyStep(0);
document.addEventListener('fig-resize', function () {
  probeGroup.clear();
  renderAll();
});
window.__markRendered();
// @FIGURE_CODE_END

